package com.mamtrex.hospital.notification;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="notifications") public class Notification extends BaseEntity { private String recipient; private String channel; private String subject; private String message; private String status; protected Notification(){} public Notification(String recipient, String channel, String subject, String message, String status){this.recipient=recipient; this.channel=channel; this.subject=subject; this.message=message; this.status=status;} public String getRecipient(){return recipient;} public String getChannel(){return channel;} public String getSubject(){return subject;} public String getMessage(){return message;} public String getStatus(){return status;} }
